/**
 * 身份锚定官 — 取证之前先锁定"这个人是谁"
 *
 * 原实现里每个信源各自消歧：维基一套规则、ORCID 一套、Scholar 直接取第一条。
 * 结果是 A 源锁定张三、B 源锁定李四，报告却把两个人的数据混在一张卡里。
 *
 * 这里先用简历本身构建一个身份指纹（姓名 / 机构 / 学科 / 时间线），
 * 再把各平台的候选主体拿来逐一比对，输出一个统一锚点。
 * 锚点之后作为所有信源的准入门槛：主体对不上的记录一律不计入互证。
 */
import { auditComplete, parseJsonLoose } from './llm';
import type { TokenTracker } from '@/lib/tools/token-tracker';
import { searchOpenAlexAuthors, type OpenAlexAuthor } from './openalexAuthor';

export interface IdentityProbe {
  name: string;
  nameEn: string;
  institutions: string[];
  researchField: string;
  degreeYears: string[];
  paperTitles: string[];
}

export interface AnchoredSubject {
  platform: 'orcid' | 'scholar' | 'openalex';
  /** 判为同一人但不是本次选用的主档案（平台上的重复档案），与"同名不同人"要分开 */
  duplicateOfAnchor?: boolean;
  id: string;
  url: string;
  displayName: string;
  affiliation: string;
  matched: boolean;
  confidence: number;
  reason: string;
}

export interface IdentityAnchor {
  probe: IdentityProbe;
  orcid: AnchoredSubject | null;
  scholar: AnchoredSubject | null;
  /** OpenAlex 作者档案：Scholar Profiles 接口下线后的学者指标主源 */
  openalex: AnchoredSubject | null;
  rejected: AnchoredSubject[];
  /** 整体锚定强度：0 未锚定 / 1 弱（仅姓名）/ 2 中（单平台确认）/ 3 强（多平台一致） */
  strength: 0 | 1 | 2 | 3;
  summary: string;
  resolvedAt: string;
}

type Log = (msg: string) => void;

function cleanName(raw: string): string {
  return (raw || '')
    .normalize('NFKC')
    .replace(/[\u2010-\u2015\u2212\uff0d]/g, '-')   // 各式连字符统一成 ASCII
    .replace(/^(?:Dr\.|Dr|Prof\.|Prof|Professor|Mr\.|Mr|Ms\.|Ms|Mrs\.|Mrs)\s+/i, '')
    .replace(/,\s*(?:Ph\.D\.|PhD|M\.D\.|MD|B\.S\.|BS|M\.S\.|MS)\s*$/i, '')
    .trim();
}

/**
 * 英文名的姓名顺序变体。
 * 中文学者在不同平台上的写法不一致：简历常写「Shi Yigong」（姓在前），
 * 而 Google Scholar / ORCID 上多是「Yigong Shi」（名在前）。
 * 顺序搞反会直接搜不到人，这里两种都给出来。
 */
export function nameOrderVariants(nameEn: string): Array<{ full: string; given: string; family: string }> {
  const clean = (nameEn || '').replace(/,/g, ' ').trim().replace(/\s+/g, ' ');
  if (!clean) return [];
  const parts = clean.split(' ').filter(Boolean);
  if (parts.length < 2) return [{ full: clean, given: clean, family: clean }];

  const a = parts[0];
  const rest = parts.slice(1).join(' ');
  const last = parts[parts.length - 1];
  const head = parts.slice(0, -1).join(' ');

  // 两种解读：首词是姓 / 末词是姓
  return [
    { full: `${rest} ${a}`, given: rest, family: a },   // Shi Yigong → Yigong Shi
    { full: `${head} ${last}`, given: head, family: last }, // 原样：Yigong Shi
    { full: clean, given: head, family: last },
  ].filter((v, i, arr) => arr.findIndex((x) => x.full.toLowerCase() === v.full.toLowerCase()) === i);
}

/** 从简历里抽出身份指纹 */
export function buildIdentityProbe(resume: Record<string, any>): IdentityProbe {
  const education = (resume.education as Array<Record<string, any>>) || [];
  const experience = (resume.experience as Array<Record<string, any>>) || [];
  const publications = (resume.publications as Array<Record<string, any>>) || [];

  return {
    name: cleanName(resume.name_cn || resume.name || ''),
    nameEn: cleanName(resume.name_en || resume.englishName || ''),
    institutions: [
      resume.primaryInstitution,
      ...experience.map((e) => e.company),
      ...education.map((e) => e.school),
    ].filter(Boolean).slice(0, 6) as string[],
    researchField: [resume.researchField, resume.title, resume.summary].filter(Boolean).join(' / ').slice(0, 300),
    degreeYears: education.map((e) => `${e.degree || ''} ${e.period || ''}`.trim()).filter(Boolean),
    paperTitles: publications.map((p) => p.title).filter(Boolean).slice(0, 8) as string[],
  };
}

// ── ORCID ────────────────────────────────────────────────────────────
async function getOrcidToken(): Promise<string | null> {
  const id = process.env.ORCID_CLIENT_ID;
  const secret = process.env.ORCID_CLIENT_SECRET;
  if (!id || !secret) return null;
  try {
    const res = await fetch('https://orcid.org/oauth/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
      body: new URLSearchParams({
        client_id: id, client_secret: secret,
        grant_type: 'client_credentials', scope: '/read-public',
      }),
      signal: AbortSignal.timeout(10000),
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data.access_token || null;
  } catch {
    return null;
  }
}

interface OrcidCandidate {
  id: string;
  name: string;
  affiliations: string[];
  works: string[];
}

async function orcidCandidates(probe: IdentityProbe, log: Log): Promise<OrcidCandidate[]> {
  const token = await getOrcidToken();
  if (!token) { log('[身份锚定] ORCID 凭证未配置，跳过 ORCID 候选检索'); return []; }

  const orders = nameOrderVariants(probe.nameEn);
------
/**
 * 证据加权 — 把验真置信度接进价值评分
 *
 * 验真线回答「这些信息是不是这个人的、可信到什么程度」，价值线在这些证据之上打分。
 * 这里把两条线接起来：每个价值维度的分数，按支撑它的验真证据的置信度做经验贝叶斯收缩——
 *
 *   ŝ_k = λ_k · s_k + (1 − λ_k) · s̄，   λ_k = λ_min + (1 − λ_min) · c_k
 *
 *   s_k  维度评审（LLM）给出的分数
 *   c_k  支撑该维度的经历卡片的平均置信度（0–1，来自 summarizeCard：多源互证 +10、存在矛盾 ×0.5）
 *   s̄    先验均值：证据不足时分数向它靠拢
 *   λ_min 证据为零时仍保留的模型权重——全景数据本身就是证据，验真没覆盖到不等于不可信
 *
 * 纯函数、不调模型，同样的输入总是同样的输出，便于回归和审计。
 */
import { assignExperienceIds, collectClaims, summarizeCard, type CardState } from './claims';

/** 证据为零时，模型分数仍保留的权重 */
export const LAMBDA_MIN = 0.5;
/** 先验均值：与维度评审解析失败时的默认分一致。后续可用历史报告按人才池、按维度统计替换 */
export const PRIOR_MEAN = 70;

/** 经历类型 → 它能为哪些价值维度提供证据 */
const DIM_EVIDENCE: Record<string, string[]> = {
  education: ['edu'],
  research: ['paper', 'project'],
  industry: ['work', 'patent'],
  leadership: ['work', 'award'],
  innovation: ['patent', 'paper', 'project'],
  social: ['award'],
};

export interface EvidenceCard {
  experienceId: string;
  state: CardState;
  confidence: number;        // 0-100
  supportingSources: number;
}

export interface DimensionEvidence {
  /** 支撑该维度的卡片数；0 表示用全体卡片均值代替 */
  cards: number;
  /** c_k，0–1 */
  confidence: number;
  /** λ_k，模型分数保留的权重 */
  weight: number;
  /** 置信度取自本维度的卡片，还是全体卡片均值 */
  basis: 'dimension' | 'overall';
}

export interface EvidenceProfile {
  /** 是否有可用的验真结果；没有时不做任何调整 */
  applied: boolean;
  cards: EvidenceCard[];
  /** 全体卡片的平均置信度，0–1 */
  overall: number;
  perDim: Record<string, DimensionEvidence>;
}

const prefixOf = (experienceId: string) => experienceId.replace(/_\d+$/, '');
const mean = (xs: number[]) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0);

/** 从验真条目算出每张经历卡片的置信度，再汇总到每个价值维度 */
export function buildEvidenceProfile(factItems: any[] = [], resume?: Record<string, any>): EvidenceProfile {
  const items = assignExperienceIds(factItems, resume).filter((f) => f.experienceId && f.experienceId !== 'other');
  const byExp = new Map<string, any[]>();
  for (const f of items) {
    if (!byExp.has(f.experienceId)) byExp.set(f.experienceId, []);
    byExp.get(f.experienceId)!.push(f);
  }

  const cards: EvidenceCard[] = [];
  for (const [experienceId, list] of byExp) {
    const s = summarizeCard(collectClaims(list));
    cards.push({ experienceId, state: s.state, confidence: s.confidence, supportingSources: s.supportingSources });
  }

  const empty: EvidenceProfile = { applied: false, cards, overall: 0, perDim: {} };
  if (!cards.length) return empty;

  const overall = mean(cards.map((c) => c.confidence)) / 100;
  const perDim: Record<string, DimensionEvidence> = {};
  for (const [dim, prefixes] of Object.entries(DIM_EVIDENCE)) {
    const own = cards.filter((c) => prefixes.includes(prefixOf(c.experienceId)));
    const confidence = own.length ? mean(own.map((c) => c.confidence)) / 100 : overall;
    perDim[dim] = {
      cards: own.length,
      confidence: round2(confidence),
      weight: round2(LAMBDA_MIN + (1 - LAMBDA_MIN) * confidence),
      basis: own.length ? 'dimension' : 'overall',
    };
  }
  return { applied: true, cards, overall: round2(overall), perDim };
}

/** ŝ_k：按证据置信度收缩后的维度分。没有验真结果时原样返回 */
export function adjustScore(score: number, dim: string, profile: EvidenceProfile): number {
  const e = profile.applied ? profile.perDim[dim] : undefined;
  if (!e) return score;
  return Math.round(e.weight * score + (1 - e.weight) * PRIOR_MEAN);
}

function round2(x: number) { return Math.round(x * 100) / 100; }

