async function scholarCandidates(probe: IdentityProbe, log: Log): Promise<ScholarCandidate[]> {
  const key = process.env.SERPAPI_KEY;
  if (!key) { log('[身份锚定] SERPAPI_KEY 未配置，跳过 Scholar 候选检索'); return []; }

  const orders = nameOrderVariants(probe.nameEn);
  const names = Array.from(new Set([
    ...orders.map((o) => o.full),
    probe.nameEn,
    probe.name,
    ...(probe.institutions[0] && orders[0] ? [`${orders[0].full} ${probe.institutions[0]}`] : []),
  ].filter(Boolean))) as string[];
  log(`[身份锚定] Scholar 检索姓名写法 ${names.length} 种：${names.slice(0, 4).join(' / ')}`);

  const out: ScholarCandidate[] = [];
  const seen = new Set<string>();

  for (const n of names) {
    if (out.length >= 5) break;
    try {
      const url = `https://serpapi.com/search.json?engine=google_scholar_profiles&mauthors=${encodeURIComponent(n)}&api_key=${key}`;
      const res = await fetch(url, { signal: AbortSignal.timeout(20000) });
      const data = await res.json();
      for (const p of data?.profiles || []) {
        if (!p.author_id || seen.has(p.author_id)) continue;
        seen.add(p.author_id);
        out.push({
          authorId: p.author_id,
          name: p.name || '',
          affiliation: p.affiliations || '',
          interests: (p.interests || []).map((i: any) => i.title || i).filter(Boolean),
          citedBy: p.cited_by || 0,
          papers: [],
        });
        if (out.length >= 5) break;
      }
    } catch { /* 忽略 */ }
  }

  // 给前两位候选补代表作，学科对不对一眼就看出来了
  for (const cand of out.slice(0, 2)) {
    try {
      const url = `https://serpapi.com/search.json?engine=google_scholar_author&author_id=${cand.authorId}&api_key=${key}&num=8`;
      const res = await fetch(url, { signal: AbortSignal.timeout(20000) });
      const data = await res.json();
      cand.papers = (data?.articles || []).slice(0, 8).map((a: any) => a.title).filter(Boolean);
    } catch { /* 忽略 */ }
  }

  log(`[身份锚定] Google Scholar 候选 ${out.length} 位`);
  return out;
}

// ── OpenAlex ─────────────────────────────────────────────────────────
async function openalexCandidates(probe: IdentityProbe, log: Log): Promise<OpenAlexAuthor[]> {
  const orders = nameOrderVariants(probe.nameEn);
  const names = Array.from(new Set([...orders.map((o) => o.full), probe.nameEn, probe.name].filter(Boolean))) as string[];

  const seen = new Set<string>();
  const out: OpenAlexAuthor[] = [];
  for (const n of names) {
    if (out.length >= 5) break;
    try {
      for (const a of await searchOpenAlexAuthors(n, 5)) {
        if (!a.id || seen.has(a.id)) continue;
        seen.add(a.id);
        out.push(a);
        if (out.length >= 5) break;
      }
    } catch (e: unknown) {
      log(`[身份锚定] OpenAlex 检索「${n}」失败：${e instanceof Error ? e.message : String(e)}`);
    }
  }
  log(`[身份锚定] OpenAlex 候选 ${out.length} 位`);
  return out;
}

// ── 判定 ─────────────────────────────────────────────────────────────
const JUDGE_RULES = `【判定准则 — 必须严格遵守】
1. 同名不等于同人。姓名一致只是入场券，必须再有机构、学科方向或代表作之一能对上，才算同一人。
2. 学科方向明显不属于同一领域的，直接判否。例如简历是肿瘤生物学，候选人的论文全是机械模具或算法，必须 matched:false。
3. 宁可漏，不可错。证据不足时判 false，并在 reason 里写明缺什么。
4. confidence 是你对"同一人"这个判断的把握（0-100），不是候选人本身的知名度。
5. reason 必须具体指出你依据的是哪条信息，不要写"信息匹配"这种空话。`;

async function judgeCandidates<T>(
  probe: IdentityProbe,
  candidates: T[],
  describe: (c: T) => string,
  platform: 'orcid' | 'scholar' | 'openalex',
  modelId: string | undefined,
  log: Log,
  tracker?: TokenTracker,
): Promise<Array<{ index: number; matched: boolean; confidence: number; reason: string }>> {
  if (candidates.length === 0) return [];

  const prompt = `你是人才背调里的身份核定员。下面是一份履历的身份指纹，以及 ${platform === 'orcid' ? 'ORCID' : platform === 'openalex' ? 'OpenAlex' : 'Google Scholar'} 上的若干候选主体。
请逐一判断每个候选主体是否就是履历中的这个人。

${JUDGE_RULES}

【履历身份指纹】
姓名：${probe.name}${probe.nameEn ? ` / ${probe.nameEn}` : ''}
关联机构：${probe.institutions.join('、') || '未知'}
研究领域：${probe.researchField || '未明确'}
学位时间线：${probe.degreeYears.join('；') || '未知'}
代表论文：${probe.paperTitles.join('；') || '未列出'}

【候选主体】
${candidates.map((c, i) => `[${i}] ${describe(c)}`).join('\n\n')}

只输出 JSON：{"results":[{"index":0,"matched":true,"confidence":85,"reason":"..."}]}`;

  const r = await auditComplete({
    modelId,
    json: true,
    temperature: 0.1,
    messages: [{ role: 'user', content: prompt }],
    log,
  });
  tracker?.track(`identity:${platform}`, r.model, r.usage);
  const raw = r.text;

  const parsed = parseJsonLoose<{ results?: Array<{ index: number; matched: boolean; confidence: number; reason: string }> }>(raw);
  const results = parsed?.results || [];
  log(`[身份锚定] ${platform} 判定完成：${results.filter((r) => r.matched).length}/${candidates.length} 判为同一人`);
  return results;
}

/** 解析身份锚点 */
export async function resolveIdentityAnchor(
  resume: Record<string, any>,
  opts: { modelId?: string; log?: Log; tracker?: TokenTracker } = {},
): Promise<IdentityAnchor> {
  const log = opts.log || (() => {});
  const probe = buildIdentityProbe(resume);

  log(`[身份锚定] 构建身份指纹：${probe.name}${probe.nameEn ? ` / ${probe.nameEn}` : ''}，机构线索 ${probe.institutions.length} 条，学科「${probe.researchField.slice(0, 40) || '未明确'}」`);

  const [orcidList, scholarList, openalexList] = await Promise.all([
    orcidCandidates(probe, log).catch(() => [] as OrcidCandidate[]),
    scholarCandidates(probe, log).catch(() => [] as ScholarCandidate[]),
    openalexCandidates(probe, log).catch(() => [] as OpenAlexAuthor[]),
  ]);

  const [orcidJudged, scholarJudged, openalexJudged] = await Promise.all([
    judgeCandidates(probe, orcidList,
      (c) => `ORCID ${c.id}｜姓名：${c.name}｜机构：${c.affiliations.join('、') || '未填写'}｜作品：${c.works.slice(0, 5).join('；') || '未获取'}`,
      'orcid', opts.modelId, log, opts.tracker).catch(() => []),
    judgeCandidates(probe, scholarList,
      (c) => `Scholar ${c.authorId}｜姓名：${c.name}｜机构：${c.affiliation || '未填写'}｜研究方向：${c.interests.join('、') || '未填写'}｜被引：${c.citedBy}｜代表作：${c.papers.slice(0, 5).join('；') || '未获取'}`,
      'scholar', opts.modelId, log, opts.tracker).catch(() => []),
    judgeCandidates(probe, openalexList,
      (c) => `OpenAlex ${c.id}｜姓名：${c.displayName}${c.alternatives.length ? `（别名：${c.alternatives.join('、')}）` : ''}｜机构：${c.institutions.join('、') || '未填写'}｜研究主题：${c.topics.join('、') || '未标注'}｜论文 ${c.worksCount} 篇｜被引 ${c.citedByCount}｜h 指数 ${c.hIndex ?? '未知'}`,
      'openalex', opts.modelId, log, opts.tracker).catch(() => []),
  ]);

  const rejected: AnchoredSubject[] = [];

  const pickBest = <T>(
    list: T[],
    judged: Array<{ index: number; matched: boolean; confidence: number; reason: string }>,
    toSubject: (c: T, j: { matched: boolean; confidence: number; reason: string }) => AnchoredSubject,
  ): AnchoredSubject | null => {
    let best: AnchoredSubject | null = null;
    for (const j of judged) {
      const cand = list[j.index];
      if (!cand) continue;
      const subject = toSubject(cand, j);
      if (j.matched && j.confidence >= 60) {
        // 判为同一人：胜出的当锚点，其余是同一主体在该平台上的重复档案
        if (!best || subject.confidence > best.confidence) {
          if (best) rejected.push({ ...best, duplicateOfAnchor: true });
          best = subject;
        } else rejected.push({ ...subject, duplicateOfAnchor: true });
      } else {
        rejected.push(subject);
      }
    }
    return best;
  };

  const orcid = pickBest(orcidList, orcidJudged, (c, j) => ({
    platform: 'orcid' as const,
    id: c.id,
    url: `https://orcid.org/${c.id}`,
    displayName: c.name,
    affiliation: c.affiliations.join('、'),
    matched: j.matched,
    confidence: j.confidence,
    reason: j.reason,
  }));

  const scholar = pickBest(scholarList, scholarJudged, (c, j) => ({
    platform: 'scholar' as const,
    id: c.authorId,
    url: `https://scholar.google.com/citations?user=${c.authorId}`,
    displayName: c.name,
    affiliation: c.affiliation,
    matched: j.matched,
    confidence: j.confidence,
    reason: j.reason,
  }));

  const openalex = pickBest(openalexList, openalexJudged, (c, j) => ({
    platform: 'openalex' as const,
    id: c.id,
    url: c.url,
    displayName: c.displayName,
    affiliation: c.institutions.join('、'),
    matched: j.matched,
    confidence: j.confidence,
    reason: j.reason,
  }));

  const hits = [orcid, scholar, openalex].filter(Boolean).length;
  const strength: IdentityAnchor['strength'] = hits >= 2 ? 3 : hits === 1 ? 2 : (probe.name ? 1 : 0);

  const anchoredNames = [orcid && 'ORCID', openalex && 'OpenAlex', scholar && 'Google Scholar'].filter(Boolean);
  const summary =
    hits >= 2 ? `已在 ${anchoredNames.join(' 与 ')} 多平台锚定同一主体`
    : hits === 1 ? `仅在 ${anchoredNames[0]} 单平台锚定到主体，其余平台未找到可确认的同一人`
    : `未能在公开学术平台锚定到该主体，后续学术类信源的记录一律不计入互证`;

  const dupes = rejected.filter((r) => r.duplicateOfAnchor).length;
  const others = rejected.length - dupes;
  const tail = [
    others ? `排除 ${others} 个同名不同人的主体` : '',
    dupes ? `合并 ${dupes} 个同一主体的重复档案` : '',
  ].filter(Boolean).join('，');
  log(`[身份锚定] ${summary}${tail ? `；${tail}` : ''}`);

  return {
    probe, orcid, scholar, openalex, rejected, strength, summary,
    resolvedAt: new Date().toISOString(),
  };
}

/**
 * 单个主体的准入判定：某个信源命中的主体，是否就是锚定的那个人。
 * 供 Scholar / ORCID handler 在取到 profile 之后调用。
 */
export function checkSubjectAgainstAnchor(
  anchor: IdentityAnchor | null | undefined,
  platform: 'orcid' | 'scholar' | 'openalex',
  subjectId: string,
): { allowed: boolean; note: string } {
  if (!anchor) return { allowed: true, note: '本次未执行身份锚定' };

  const target = platform === 'orcid' ? anchor.orcid : platform === 'openalex' ? anchor.openalex : anchor.scholar;

  if (target) {
    if (!subjectId) return { allowed: false, note: `身份锚定指向 ${target.id}，本次命中的主体没有 id，无法确认为同一人` };
    const same = subjectId.replace(/\s/g, '') === target.id.replace(/\s/g, '');
    return same
      ? { allowed: true, note: `与身份锚点一致（置信度 ${target.confidence}）：${target.reason}` }
      : { allowed: false, note: `命中主体 ${subjectId} 与身份锚点 ${target.id} 不是同一人，该记录不计入互证` };
  }

  const wasRejected = anchor.rejected.find((r) => r.platform === platform && r.id === subjectId);
  if (wasRejected) {
    return { allowed: false, note: `身份锚定阶段已排除该主体：${wasRejected.reason}` };
  }

  return { allowed: false, note: `身份锚定未能在该平台确认同一人，本条记录仅作参考，不计入互证` };
}

