/** 断言与声明的关系 */
export type Verdict =
  | 'support'       // 信源记录支持该声明
  | 'contradict'    // 信源记录与声明矛盾
  | 'insufficient'  // 信源有该主体，但这条信息不足以判断
  | 'not_found';    // 信源中没有相关记录

export const VERDICT_META: Record<Verdict, { label: string; color: string; bg: string }> = {
  support:      { label: '支持',     color: '#047857', bg: 'rgba(16,185,129,0.10)' },
  contradict:   { label: '矛盾',     color: '#b91c1c', bg: 'rgba(239,68,68,0.10)' },
  insufficient: { label: '证据不足', color: '#b45309', bg: 'rgba(245,158,11,0.10)' },
  not_found:    { label: '未找到',   color: '#64748b', bg: 'rgba(100,116,139,0.10)' },
};

export interface SourceClaim {
  id: string;
  /** 归属的经历（edu_0 / work_1 / paper_0 …） */
  experienceId: string;
  sourceKey: SourceKey;
  sourceName: string;
  sourceUrl?: string;
  /** 被核查的字段 */
  field: string;
  /** 简历中的声明 */
  claim: string;
  /** 信源中的实际记录 */
  found: string | null;
  /** 断言句：这个信源就该字段做出的陈述（不是最终结论） */
  assertion: string;
  verdict: Verdict;
  /** 0-100 */
  confidence: number;
  /** 置信度是怎么来的 */
  confidenceBasis: string;
  evidence: string[];
  retrievedAt: string;
  /** 存证摘要：对断言内容做哈希，便于事后验证这条记录未被篡改 */
  digest: string;
  /** 该信源命中的主体是否通过了身份锚定；null 表示本次未做锚定判断 */
  subjectAnchored: boolean | null;
  /** 锚定未通过时的说明 */
  anchorNote?: string;
}

/** 对断言内容取存证摘要 */
export function digestOf(parts: Record<string, unknown>): string {
  return createHash('sha256').update(JSON.stringify(parts)).digest('hex').slice(0, 16);
}

export function makeClaim(input: Omit<SourceClaim, 'id' | 'digest' | 'retrievedAt'> & { retrievedAt?: string }): SourceClaim {
  // 显式传空串 = 这条断言没有取证时间（存量 factItem 就是如此）。
  // 不能拿 now 顶替：摘要会跟着每次渲染变，存证就失去意义了，服务端与客户端也对不上。
  const retrievedAt = input.retrievedAt !== undefined ? input.retrievedAt : new Date().toISOString();
  const digest = digestOf({
    s: input.sourceKey, f: input.field, c: input.claim,
    fo: input.found, v: input.verdict, e: input.evidence, t: retrievedAt,
  });
  return {
    ...input,
    id: `${input.experienceId}:${input.sourceKey}:${digest.slice(0, 8)}`,
    retrievedAt,
    digest,
  };
}

